  [UnityTest,Category("WhistleDiscovery"),Timeout(90000)]public IEnumerator NativeSenseCostIsMeasuredWithoutGrowingRenderersOrSources(){var tool=WhistleSystem.For(game);tool.LearnLore();game.player.Warp(new Vector3(45.4f,.05f,46.2f),180);yield return null;yield return null;var sense=game.GetComponent<WhistleSense>();int sources=UnityEngine.Object.FindObjectsByType<AudioSource>(FindObjectsInactive.Include).Length;int renderers=UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsInactive.Include).Length;var timer=new System.Diagnostics.Stopwatch();long before=GC.GetAllocatedBytesForCurrentThread();timer.Start();tool.BlowTap();timer.Stop();long cold=GC.GetAllocatedBytesForCurrentThread()-before;double coldMs=timer.Elapsed.TotalMilliseconds;for(int i=0;i<12;i++){tool.State.cooldownRemaining=0;tool.BlowTap();}long total=0,peak=0,ticks=0,maxTicks=0;for(int i=0;i<64;i++){tool.State.cooldownRemaining=0;before=GC.GetAllocatedBytesForCurrentThread();timer.Restart();tool.BlowTap();timer.Stop();long bytes=GC.GetAllocatedBytesForCurrentThread()-before;total+=bytes;peak=Math.Max(peak,bytes);ticks+=timer.ElapsedTicks;maxTicks=Math.Max(maxTicks,timer.ElapsedTicks);}Assert.That(sense.ActiveCount,Is.GreaterThan(0));Assert.That(sense.BufferSaturated,Is.False);Assert.That(UnityEngine.Object.FindObjectsByType<AudioSource>(FindObjectsInactive.Include).Length,Is.EqualTo(sources));Assert.That(UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsInactive.Include).Length,Is.EqualTo(renderers));var result=new WhistleSenseMeasurement{samples=64,highlighted=sense.ActiveCount,overlaps=sense.LastOverlapCount,saturated=sense.BufferSaturated,averageBytes=total/64,peakBytes=peak,averageMs=ticks*1000d/System.Diagnostics.Stopwatch.Frequency/64,peakMs=maxTicks*1000d/System.Diagnostics.Stopwatch.Frequency,coldBytes=cold,coldMs=coldMs,scope="Native school; synchronous whistle, bounded overlap and LOS, cached highlights and actual audio pool. Cooldown bypassed only in benchmark. Deferred responses, fade frames, save I/O and GPU timing excluded."};var dir="C:/Users/ruhtra/Documents/Codex/2026-09-29/oi/outputs/WhistleXray20261031";Directory.CreateDirectory(dir);File.WriteAllText(dir+"/performance.json",JsonUtility.ToJson(result,true));}
